(470, 60, 427, 30, 'matching', 'Match the plant part with an example food.', '[\"Root | Carrot\",\"Stem | Celery\",\"Leaf | Spinach\",\"Flower | Broccoli\",\"Fruit | Pepper\",\"Seed | Sunflower seed\",\"Sensor | DHT11\",\"Actuator | Relay module\",\"Microcontroller | ESP32 board\",\"IoT device | Smart thermostat\"]', 'Root | Carrot; Stem | Celery; Leaf | Spinach; Flower | Broccoli; Fruit | Pepper; Seed | Sunflower seed; Sensor | DHT11; Actuator | Relay module; Microcontroller | ESP32 board; IoT device | Smart thermostat', 10.00, NULL, '2026-11-21 11:13:00'),
