INSERT INTO `assessment_questions` (`id`, `assessment_id`, `question_bank_id`, `sort_order`, `item_type`, `question`, `choices`, `answer`, `points`, `rubric`, `created_at`) VALUES
(46207, 8772, 469, 3, 'mcq', 'Which is a helping verb?', '[\"is\",\"cat\",\"red\",\"fast\"]', 'is', 1.00, NULL, '2026-11-27 03:38:44'),
(46208, 8772, 470, 4, 'mcq', 'Which word is an adjective?', '[\"big\",\"run\",\"she\",\"dog\"]', 'big', 1.00, NULL, '2026-11-27 03:38:44'),
(46209, 8772, 471, 5, 'true_false', 'Nouns can be people, places, or things.', '[\"True\",\"False\"]', 'True', 1.00, NULL, '2026-11-27 03:38:44'),
(46210, 8772, 472, 6, 'true_false', 'Verbs tell us about feelings.', '[\"True\",\"False\"]', 'False', 1.00, NULL, '2026-11-27 03:38:44'),
(46211, 8772, 473, 7, 'true_false', 'The word \"she\" is a pronoun.', '[\"True\",\"False\"]', 'True', 1.00, NULL, '2026-11-27 03:38:44'),
(46212, 8772, 474, 8, 'true_false', 'Adding an \"s\" makes a noun plural.', '[\"True\",\"False\"]', 'True', 1.00, NULL, '2026-11-27 03:38:44'),
(46213, 8772, 475, 9, 'true_false', 'Adverbs modify nouns.', '[\"True\",\"False\"]', 'False', 1.00, NULL, '2026-11-27 03:38:44'),
(46214, 8772, 476, 10, 'fill_blank', 'The rabbit ___ the book.', '[\"read\",\"blue\",\"dog\",\"she\"]', 'read', 1.00, NULL, '2026-11-27 03:38:44'),
(46215, 8772, 477, 11, 'fill_blank', 'Anna ___ France.', '[\"visited\",\"run\",\"big\",\"is\"]', 'visited', 1.00, NULL, '2026-11-27 03:38:44'),
(46216, 8772, 478, 12, 'fill_blank', 'She owns two ____.', '[\"dogs\",\"run\",\"blue\",\"she\"]', 'dogs', 1.00, NULL, '2026-11-27 03:38:44'),
(46217, 8772, 479, 13, 'fill_blank', 'Beyoncé ____ singing.', '[\"is\",\"dog\",\"happy\",\"jump\"]', 'is', 1.00, NULL, '2026-11-27 03:38:44'),
(46218, 8772, 480, 14, 'fill_blank', 'The ____ girl is tall.', '[\"intelligent\",\"run\",\"dog\",\"she\"]', 'intelligent', 1.00, NULL, '2026-11-27 03:38:44');
